                    callback.onFailure(request, new Throwable(message), 1);
                }
                catch (Exception e) {
                    callback.onFailure(request, e, 1);
                }
            } else {
                String message = "HTTP Error Code: %d, Response %s".formatted(response.statusCode(), response);
                callback.onFailure(request, new Throwable(message), 1);
            }
        }
    }
}

